fn cleanup_expired_gateways(dbtx: &mut DatabaseTransaction<'_>) -> anyhow::Result<()> {
    let mut stream = dbtx.scan_prefix(LightningGatewayKeyPrefix::Registration);
    let mut deleted_count = 0;

    while let Some(item) = stream.next().await {
        let (key, value) = item?;
        let registration: LightningGatewayRegistration = value?;

        if registration.is_expired() {
            dbtx.delete(key)?;
            deleted_count += 1;
        }
    }

    tracing::info!("Deleted {} expired gateway registrations", deleted_count);
    Ok(())
}

