use fedimint_core::db::DatabaseTransaction;
use fedimint_core::Amount;
use fedimint_mint_server::db::{MintAuditItemKey, MintAuditItemKeyPrefix};
use anyhow::Result;

fn calculate_mint_audit_totals(
    dbtx: &mut DatabaseTransaction<'_>
) -> Result<(Amount, Amount)> {
    let issued_total = Amount::ZERO;
    let redeemed_total = Amount::ZERO;

    // Iterate over all audit items with the "issued" prefix
    for item in dbtx.iter_prefix(MintAuditItemKeyPrefix::Issued) {
        if let Some(key) = item.key {
            if let Some(value) = item.value {
                if let Ok(amount) = Amount::from_bytes(value) {
                    issued_total += amount;
                }
            }
        }
    }

    // Iterate over all audit items with the "redeemed" prefix
    for item in dbtx.iter_prefix(MintAuditItemKeyPrefix::Redeemed) {
        if let Some(key) = item.key {
            if let Some(value) = item.value {
                if let Ok(amount) = Amount::from_bytes(value) {
                    redeemed_total += amount;
                }
            }
        }
    }

    Ok((issued_total, redeemed_total))
}

