use std::ffi::CString;
use std::sync::atomic::AtomicUsize;
use crate::c::{TSHighlighter, TSHighlightBuffer, ts_highlight_buffer_new, ts_highlighter_highlight, ts_highlight_buffer_content, ts_highlight_buffer_len, ts_highlight_buffer_delete};

fn highlight_to_html(
    highlighter: &TSHighlighter,
    scope_name: &str,
    source: &str,
) -> Result<String, ErrorCode> {
    let c_scope_name = CString::new(scope_name).map_err(|_| ErrorCode::InvalidInput)?;
    let c_source = CString::new(source).map_err(|_| ErrorCode::InvalidInput)?;

    let buffer = ts_highlight_buffer_new();
    if buffer.is_null() {
        return Err(ErrorCode::MemoryAllocationFailed);
    }

    let result = unsafe { ts_highlighter_highlight(highlighter, buffer, c_scope_name.as_ptr(), c_source.as_ptr()) };
    if result != 0 {
        return Err(ErrorCode::HighlightingFailed);
    }

    let html = unsafe { ts_highlight_buffer_content(buffer) };
    let len = unsafe { ts_highlight_buffer_len(buffer) };

    if html.is_null() || len == 0 {
        ts_highlight_buffer_delete(buffer);
        return Err(ErrorCode::EmptyOutput);
    }

    let html_str = unsafe { std::slice::from_raw_parts(html as *const u8, len as usize) };
    let html_result = String::from_utf8(html_str.to_vec()).map_err(|_| ErrorCode::InvalidEncoding)?;

    unsafe { ts_highlight_buffer_delete(buffer) };

    Ok(html_result)
}

use std::io;
use std::error::Error;
use ext_sort::{ExternalSorter, SortError};

fn process_sorted_in_batches<T, E, F>(
    sorter: &ExternalSorter<T, E>,
    input: impl IntoIterator<Item = Result<T, E>>,
    batch_size: usize,
    mut processor: F,
) -> Result<(), SortError<E, E, E>>
where
    T: Ord + Clone + Send,
    F: FnMut(&[T]) -> Result<(), io::Error>,
    E: Error,
{
    let mut buffer = Vec::new();
    let mut input_iter = input.into_iter();

    while let Some(result) = input_iter.next() {
        let item = result?;
        buffer.push(item);

        if buffer.len() >= batch_size {
            processor(&buffer)?;
            buffer.clear();
        }
    }

    if !buffer.is_empty() {
        processor(&buffer)?;
    }

    Ok(())
}

