fn register_gateway_safe(
    &self,
    dbtx: &mut DatabaseTransaction<'_>,
    gateway: LightningGatewayAnnouncement,
) -> Result<(), Error> {
    // Check for existing gateway with overlapping expiration
    let existing_gateways = LightningGatewayKey::iter(dbtx)
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for existing_key in existing_gateways {
        let existing_announcement = LightningGatewayKey::get(dbtx, &existing_key)?;
        if is_overlap(&existing_announcement, &gateway) {
            return Err(anyhow!("Gateway with overlapping expiration already exists"));
        }
    }

    // Clean up expired gateways
    cleanup_expired_gateways(dbtx)?;

    // Register the new gateway
    LightningGatewayKey::insert(dbtx, &gateway.key, &gateway)?;

    Ok(())
}

fn is_overlap(
    existing: &LightningGatewayAnnouncement,
    new: &LightningGatewayAnnouncement,
) -> bool {
    // Check if the new gateway's time range overlaps with the existing one
    let existing_start = existing.expiry_time;
    let existing_end = existing.expiry_time + existing.expiry_duration;
    let new_start = new.expiry_time;
    let new_end = new.expiry_time + new.expiry_duration;

    // Overlap exists if the intervals [existing_start, existing_end) and [new_start, new_end) intersect
    existing_start < new_end && new_start < existing_end
}

fn cleanup_expired_gateways(
    dbtx: &mut DatabaseTransaction<'_>,
) -> Result<(), Error> {
    let expired_gateways = LightningGatewayKey::iter(dbtx)
        .filter(|(_, announcement)| announcement.expiry_time <= std::time::SystemTime::now())
        .map(|(key, _)| key)
        .collect::<Vec<_>>();

    for key in expired_gateways {
        LightningGatewayKey::delete(dbtx, &key)?;
    }

    Ok(())
}

