use fractional_index::FractionalIndex;

fn generate_spaced_indices(
    lower: &FractionalIndex,
    upper: &FractionalIndex,
    count: usize,
) -> Vec<FractionalIndex> {
    if count == 0 {
        return Vec::new();
    }

    let mut result = Vec::with_capacity(count);
    let total = upper.0 - lower.0;

    for i in 0..count {
        let fraction = (i as f64) / (count as f64);
        let value = lower.0 + fraction * total;
        result.push(FractionalIndex(value));
    }

    result
}

