fn scan_range_with_cursor(
    kv: &Kv,
    prefix: Vec<deno_kv::interface::AnyValue>,
    limit: u32,
) -> Result<Vec<deno_kv::interface::KvEntry<unknown>>, KvError> {
    let mut entries = Vec::new();
    let mut cursor = Vec::new();

    loop {
        let selector = RawSelector::new(prefix.clone(), None);
        let options = KvListOptions::new().with_limit(limit).with_cursor(cursor);
        let list_result = kv.list(selector, options)?;

        entries.extend(list_result.entries);

        if list_result.cursor.is_empty() {
            break;
        }

        cursor = list_result.cursor;
    }

    Ok(entries)
}

fn persist_state<T: Target>(router: &RouterContext<T>, state: State) -> State {
    if let Some(window) = window() {
        let storage = window.local_storage().ok_or(JsValue::from("Local storage not available")).unwrap();
        let serialized = serde_wasm_bindgen::to_value(&state).map_err(|e| JsValue::from(e.to_string())).unwrap();
        storage.set_item("router_state", &serialized).ok();
    }

    if let Some(window) = window() {
        let storage = window.local_storage().ok_or(JsValue::from("Local storage not available")).unwrap();
        if let Some(serialized) = storage.get_item("router_state") {
            if let Ok(restored_state) = serde_wasm_bindgen::from_value(serialized) {
                return restored_state;
            }
        }
    }

    state
}

