    Katakana,
    Alphabet,
    Number,
    Other,
}

fn determine_token_type(token: &str) -> TokenType {
    let mut has_kanji = false;
    let mut has_hiragana = false;
    let mut has_katakana = false;
    let mut has_alphabet = false;
    let mut has_number = false;

    for c in token.chars() {
        let ctype = get_ctype(c);
        match ctype {
            'M' => has_kanji = true,
            'H' => has_hiragana = true,
            'I' => has_hiragana = true,
            'K' => has_katakana = true,
            'A' => has_alphabet = true,
            'N' => has_number = true,
            _ => {}
        }
    }

    if has_kanji {
        return TokenType::Kanji;
    } else if has_hiragana {
        return TokenType::Hiragana;
    } else if has_katakana {
        return TokenType::Katakana;
    } else if has_alphabet {
        return TokenType::Alphabet;
    } else if has_number {
        return TokenType::Number;
    } else {
        return TokenType::Other;
    }
}

