    sma1: &impl SMA<S, D, N>,
    sma2: &impl SMA<S, D, N>,
) -> SumTreeSMA<S, D, N>
where
    S: Copy + std::ops::Add<Output = S> + std::ops::Div<D, Output = S> + num_traits::Zero,
    D: FromPrimitive,
{
    let mut merged = SumTreeSMA::new();
    let mut sum = S::zero();
    let mut count = D::from_usize(0).unwrap();

    for i in 0..N {
        sum = sum + sma1.get(i) + sma2.get(i);
        count = count + D::from_usize(1).unwrap();
    }

    merged.set_sum(sum);
    merged.set_count(count);

    merged
}

