fn batch_convert_json_to_jcs(directory: &str) -> std::io::Result<()> {
    if !Path::new(directory).exists() {
        return Err(std::io::Error::new(std::io::ErrorKind::NotFound, format!("Directory not found: {}", directory)));
    }

    let entries = fs::read_dir(directory)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext == "json") {
            let content = fs::read_to_string(&path)?;
            let canonicalized = pipe(&content);
            let new_path = path.with_extension("jcs");

            fs::write(new_path, canonicalized)?;
        }
    }

    Ok(())
}

fn cose_key_to_jwk(key: &CoseKey) -> Result<serde_json::Value, KeyDecodingError> {
    let mut jwk = serde_json::Map::new();
    let key_type = match key.key_type() {
        KeyType::EC2 => "EC2",
        KeyType::OKP => "OKP",
        _ => return Err(KeyDecodingError::UnsupportedKeyType),
    };
    jwk.insert(serde_json::json!("kty"), serde_json::json!(key_type));

    match key.key_type() {
        KeyType::EC2 => {
            let crv = match key.get(Label::Crv) {
                Some(crv) => crv,
                None => return Err(KeyDecodingError::MissingParameter("crv".to_string())),
            };
            let x = match key.get(Label::X) {
                Some(x) => x,
                None => return Err(KeyDecodingError::MissingParameter("x".to_string())),
            };
            let y = match key.get(Label::Y) {
                Some(y) => y,
                None => return Err(KeyDecodingError::MissingParameter("y".to_string())),
            };

            let crv_str = match crv {
                crate::key::EC2_CRV::P256 => "P-256",
                crate::key::EC2_CRV::P384 => "P-384",
                crate::key::EC2_CRV::P521 => "P-521",
                _ => return Err(KeyDecodingError::UnsupportedCurve),
            };
            jwk.insert(serde_json::json!("crv"), serde_json::json!(crv_str));

            let x_bytes = match x {
                crate::key::EC2_X::OctetString(x) => x,
                _ => return Err(KeyDecodingError::InvalidParameter("x".to_string())),
            };
            let x_str = base64::Engine::encode(&URL_SAFE_NO_PAD, x_bytes);
            jwk.insert(serde_json::json!("x"), serde_json::json!(x_str));

            let y_bytes = match y {
                crate::key::EC2_Y::OctetString(y) => y,
                _ => return Err(KeyDecodingError::InvalidParameter("y".to_string())),
            };
            let y_str = base64::Engine::encode(&URL_SAFE_NO_PAD, y_bytes);
            jwk.insert(serde_json::json!("y"), serde_json::json!(y_str));
        }
        KeyType::OKP => {
            let crv = match key.get(Label::Crv) {
                Some(crv) => crv,
                None => return Err(KeyDecodingError::MissingParameter("crv".to_string())),
            };
            let x = match key.get(Label::X) {
                Some(x) => x,
                None => return Err(KeyDecodingError::MissingParameter("x".to_string())),
            };

            let crv_str = match crv {
                crate::key::OKP_CRV::Ed25519 => "Ed25519",
                crate::key::OKP_CRV::Ed448 => "Ed448",
                _ => return Err(KeyDecodingError::UnsupportedCurve),
            };
            jwk.insert(serde_json::json!("crv"), serde_json::json!(crv_str));

            let x_bytes = match x {
                crate::key::OKP_X::OctetString(x) => x,
                _ => return Err(KeyDecodingError::InvalidParameter("x".to_string())),
            };
            let x_str = base64::Engine::encode(&URL_SAFE_NO_PAD, x_bytes);
            jwk.insert(serde_json::json!("x"), serde_json::json!(x_str));
        }
        _ => return Err(KeyDecodingError::UnsupportedKeyType),
    }

    Ok(serde_json::Value::Object(jwk))
}

