use wasmcloud_component::wasi::config::store;
use wasmcloud_component::wasi::random::random;
use base64;
use anyhow;

fn get_or_generate_token(key: &str) -> Result<String, anyhow::Error> {
    // Try to retrieve the token from the config store
    let token = store::get(key)?;
    if !token.is_empty() {
        return Ok(token);
    }

    // Generate a new 32-byte random token
    let mut token_bytes = [0u8; 32];
    random::get(&mut token_bytes)?;

    // Base64-encode the token
    let token_str = base64::encode(&token_bytes);

    // Save the token to the config store
    store::set(key, &token_str)?;

    Ok(token_str)
}

use gluesql_core::store::{StoreMut, DataRow};
use gluesql_core::data::Value;
use gluesql_core::error::Result;
use futures::stream::TryStreamExt;

fn validate_column_type(store: &dyn StoreMut, table_name: &str, column_name: &str, expected_type: &str) -> Result<()> {
    let mut rows = store.scan(table_name).try_stream()?;
    while let Some(row) = rows.next().await {
        let row = row?;
        if let Some(value) = row.get(column_name) {
            if !matches_value(value, expected_type) {
                return Err(format!("Mismatched type for column '{}': expected '{}', got '{}'", column_name, expected_type, value).into());
            }
        }
    }
    Ok(())
}

fn matches_value(value: &Value, expected_type: &str) -> bool {
    match value {
        Value::Int(i) => expected_type == "INT" || expected_type == "INTEGER",
        Value::BigInt(i) => expected_type == "BIGINT",
        Value::Real(f) => expected_type == "REAL" || expected_type == "FLOAT",
        Value::Text(s) => expected_type == "TEXT",
        Value::Bool(b) => expected_type == "BOOLEAN" || expected_type == "BOOL",
        Value::Null => expected_type == "NULL",
        _ => false,
    }
}

fn atomic_increment(
