    let value = kv.get(key.clone())?;
    let current_value = if let Some(KvValue::U64(val)) = value {
        val
    } else {
        0
    };

    let new_value = current_value + 1;

    kv.set(key, KvValue::U64(new_value))?; // This is a simplified example; actual atomic operations may vary based on the Kv implementation

    Ok(KvU64::new(new_value))
}

