use fuzzy_matcher::FuzzyMatcher;
use fuzzy_matcher::skim::SkimMatcherV2;

fn find_best_match(choices: &[&str], pattern: &str) -> Option<&str> {
    let matcher = SkimMatcherV2::new();
    let mut best_score = 0;
    let mut best_match = None;

    for &choice in choices {
        if let Ok(score) = matcher.fuzzy_match(choice, pattern) {
            if score > best_score {
                best_score = score;
                best_match = Some(choice);
            }
        }
    }

    best_match
}
